commands.command:
install -d -m 0750 -o root -g root /var/log/inventory && cat > /etc/rsyslog.d/30-inventory-collector.conf <<'ANTRIEB_EOF'
module(load="imtcp")
input(type="imtcp" port="514" ruleset="inventoryRemote")

ruleset(name="inventoryRemote") {
    if ($fromhost-ip == '10.100.46.11' and $programname == 'inventory') then {
        action(type="omfile" file="/var/log/inventory/node2.log" fileOwner="root" fileGroup="root" fileCreateMode="0640" dirCreateMode="0750" createDirs="on")
        stop
    }
}
ANTRIEB_EOF
restorecon -RF /var/log/inventory /etc/rsyslog.d/30-inventory-collector.conf && rsyslogd -N1
